/* Generated by gen_packs.py from the original data files: pack "psylocke". */
MC.registerPack({"id":"psylocke","cards":[{"id":"41001a","name":"사일록","en":"* Psylocke","type":"hero","enc":false,"unique":true,"hp":10,"atk":1,"thw":1,"def":2,"hs":4,"tr":["PSIONIC","X-FORCE"],"traits":["사이오닉","엑스포스"],"text":"[star] <i>사이 에너지 제어</i> — <b>난입</b>: 당신이 사일록의 기본 기능 중 하나를 사용할 때<i>(저지, 공격, 방어)</i>, [[사이 에너지]] 업그레이드 1장을 뒤집습니다.","star":true},{"id":"41001b","name":"벳시 브래독","en":"* Betsy Braddock","type":"alter","enc":false,"unique":true,"hp":10,"rec":3,"hs":6,"tr":["MUTANT","PSIONIC"],"traits":["뮤턴트","사이오닉"],"text":"<i>사이오닉 발현</i> — <b>사전 준비</b>: 당신의 [[사이 에너지]] 업그레이드 2장을 사이 나이프 면이 앞면이 되도록 플레이 영역에 내려놓습니다.\n<b>행동</b>: [[사이 에너지]] 업그레이드 1장을 소진 → 당신의 버린 더미에서 [[사이오닉]] 카드 1장을 당신의 덱에 섞어 넣음."},{"id":"41002a","name":"사이 나이프","en":"Psi-Knife","type":"upgrade","enc":false,"unique":false,"res":"B","cls":"Hero","tr":["PSI-ENERGY","WEAPON"],"permanent":1,"traits":["사이 에너지","무기"],"text":"영속.\n사일록은 저지 +1을 받습니다.\n<b>히어로 자원</b>: 사이 나이프를 소진 → [mental] 자원을 생성. 이 카드를 뒤집어도 됨."},{"id":"41002b","name":"사이 카타나","en":"Psi-Katana","type":"upgrade","enc":false,"unique":false,"res":"R","cls":"Hero","tr":["PSI-ENERGY","WEAPON"],"permanent":1,"restricted":1,"traits":["사이 에너지","무기"],"text":"영속. 한정.\n사일록은 공격 +1을 받고 그녀의 기본 공격은 관통을 얻습니다.\n<b>히어로 자원</b>: 사이 카타나를 소진 → [physical] 자원을 생성. 이 카드를 뒤집어도 됨."},{"id":"41003","name":"엔젤","en":"* Angel","type":"ally","enc":false,"sub":"워렌 워딩턴 3세","unique":true,"hp":3,"atk":2,"atkStar":true,"thw":1,"thwStar":true,"cost":3,"res":"G","cls":"Hero","tr":["AERIAL","X-FORCE"],"traits":["공중","엑스포스"],"text":"<b>반응</b>: 당신의 손에서 엔젤을 플레이한 후, 당신의 아이덴티티를 준비합니다."},{"id":"41004","name":"칼날 세례","en":"Flurry of Blades","type":"event","enc":false,"unique":false,"cost":3,"res":"Y","cls":"Hero","tr":["ATTACK","PSIONIC"],"traits":["공격","사이오닉"],"text":"<b>히어로 행동</b><i>(공격)</i>: 적 하나에게 피해 2점을 입힙니다. 당신이 조종하는 사이 나이프마다, 적 하나를 선택해 혼란에 빠뜨립니다. 당신이 조종하는 사이 카타나마다, 적 하나를 선택해 피해 2점을 입힙니다."},{"id":"41005","name":"정신 감지","en":"Mental Detection","type":"event","enc":false,"unique":false,"cost":2,"res":"B","cls":"Hero","tr":["PSIONIC","THWART"],"traits":["사이오닉","저지"],"text":"<b>히어로 행동</b><i>(저지)</i>: 음모 하나에서 위협을 1만큼 제거합니다. 당신이 조종하는 사이 나이프마다, 그 음모에서 위협을 2만큼 추가로 제거합니다. 당신이 조종하는 사이 카타나마다, 카드 1장을 뽑습니다."},{"id":"41006","name":"사이오닉 전환","en":"Psionic Redirect","type":"event","enc":false,"unique":false,"cost":2,"res":"B","cls":"Hero","tr":["DEFENSE","PSIONIC"],"traits":["방어","사이오닉"],"text":"<b>히어로 난입</b><i>(방어)</i>: 당신이 적의 공격으로 피해를 입으려 할 때, 그 피해에서 2점을 방지합니다. 당신이 조종하는 사이 카타나마다, 피해 2점을 추가로 방지합니다. 당신이 조종하는 사이 나이프마다, 그 적을 혼란에 빠뜨립니다."},{"id":"41007","name":"텔레파시 암시","en":"Telepathic Suggestion","type":"event","enc":false,"unique":false,"cost":2,"res":"Y","cls":"Hero","tr":["PSIONIC"],"traits":["사이오닉"],"text":"<b>히어로 난입</b>: 당신이 조우 덱에서 카드를 공개할 때, 그 카드의 \"<b>공개될 때</b>\" 효과를 무효화합니다. 당신이 조종하는 사이 카타나마다, 적 하나를 선택해 피해 2점을 입힙니다. 당신이 조종하는 사이 나이프마다, 음모 하나를 선택해 위협을 1만큼 제거합니다."},{"id":"41008","name":"훈련 일과","en":"Training Regimen","type":"support","enc":false,"unique":false,"cost":1,"res":"R","cls":"Hero","tr":["TRAINING"],"traits":["훈련"],"text":"<b>행동</b>: 훈련 일과를 소진 → 당신의 덱에서 [[기술]] 카드 1장을 찾아 당신의 손에 더함. <i>(덱을 섞습니다.)</i> 당신이 히어로 형태라면, 당신의 손에서 카드 1장을 버림."},{"id":"41009","name":"무술 훈련","en":"Martial Arts Training","type":"upgrade","enc":false,"unique":false,"cost":1,"res":"R","cls":"Hero","tr":["SKILL"],"traits":["기술"],"text":"사일록은 방어 +1을 받습니다.\n<b>히어로 반응</b>: 사일록이 공격을 방어한 후, 무술 훈련을 버림 → 사일록을 준비."},{"id":"41010","name":"사이오닉 훈련","en":"Psionic Training","type":"upgrade","enc":false,"unique":false,"cost":1,"res":"B","cls":"Hero","tr":["SKILL"],"traits":["기술"],"text":"사일록은 경호와 순찰 키워드를 무시합니다.\n<b>히어로 반응</b>: 사일록이 저지한 후, 사이오닉 훈련을 버림 → 적 하나를 혼란에 빠뜨림."},{"id":"41011","name":"무기 훈련","en":"Weapons Training","type":"upgrade","enc":false,"unique":false,"cost":2,"res":"R","cls":"Hero","tr":["SKILL"],"traits":["기술"],"text":"사일록은 반격 1을 얻습니다.\n<b>히어로 반응</b>: 사일록이 공격한 후, 무기 훈련을 버림 → 당신이 조종하는 각 [[무기]] 업그레이드를 준비."},{"id":"41012","name":"캡틴 브리튼","en":"* Captain Britain","type":"ally","enc":false,"sub":"브라이언 브래독","unique":true,"hp":3,"atk":3,"atkStar":true,"atkCons":2,"thw":3,"thwStar":true,"thwCons":2,"cost":4,"res":"B","cls":"Justice","tr":["AERIAL","EXCALIBUR"],"traits":["공중","엑스칼리버"],"text":"[star] 캡틴 브리튼은 부가 음모를 저지하거나 하수인을 공격한 후, 부수적 피해를 1 덜 입습니다.","star":true},{"id":"41013","name":"사이퍼","en":"* Cypher","type":"ally","enc":false,"sub":"더그 램지","unique":true,"hp":2,"atk":1,"atkStar":true,"thw":1,"thwStar":true,"cost":2,"res":"Y","cls":"Justice","tr":["X-FORCE"],"traits":["엑스포스"],"text":"[star] <b>반응</b>: 사이퍼가 혼란 상태인 적을 공격하여 피해를 입힌 후, 카드 1장을 뽑습니다.","star":true},{"id":"41014","name":"진탕성 타격","en":"Concussive Blow","type":"event","enc":false,"unique":false,"cost":3,"res":"R","cls":"Justice","tr":["ATTACK"],"traits":["공격"],"text":"<b>히어로 행동</b><i>(공격)</i>: 적 하나를 혼란에 빠뜨립니다. 이 카드에 [physical] 자원을 지불했다면, 그 적에게 피해 3점을 입힙니다."},{"id":"41015","name":"뒤통수 한 대","en":"Upside the Head","type":"event","enc":false,"unique":false,"cost":1,"res":"B","cls":"Justice","tr":["SKILL"],"traits":["기술"],"text":"<b>히어로 반응</b>: 당신의 히어로가 기본 공격을 하여 적에게 피해를 입힌 후, 그 적을 혼란에 빠뜨립니다. 그 적이 이미 혼란 상태라면, 대신 그 적을 기절시킵니다."},{"id":"41016","name":"덫 놓기","en":"* Lay the Trap","type":"pside","enc":false,"unique":true,"cost":1,"start":3,"startStar":true,"res":"Y","cls":"Justice","tr":[],"victory":0,"traits":[],"text":"승점 0.\n<b>격파될 때</b>: 이 음모를 격파한 플레이어가 빌런에게 피해 5[per_hero]점을 입힙니다."},{"id":"41017","name":"나비처럼 날아서","en":"Float Like a Butterfly","type":"upgrade","enc":false,"unique":false,"cost":2,"res":"Y","cls":"Justice","tr":["SKILL"],"maxPer":1,"traits":["기술"],"text":"이 카드를 플레이하면, 조종할 플레이어를 정합니다.\n플레이어마다 최대 1장.\n<b>난입</b>: 당신이 조종하는 캐릭터가 혼란 상태인 적을 공격할 때, 그 공격이 그 적에게 입히는 피해를 1 늘립니다."},{"id":"41018","name":"피트 위즈덤","en":"* Pete Wisdom","type":"ally","enc":false,"unique":true,"hp":3,"atk":2,"atkStar":true,"thw":3,"thwStar":true,"thwCons":2,"cost":4,"res":"B","cls":"Basic","tr":["X-FORCE"],"traits":["엑스포스"],"text":"당신의 아이덴티티에게 [[엑스포스]] 특성이 있을 때만 플레이합니다.\n<b>반응</b>: 당신이 배반 카드의 \"<b>공개될 때</b>\" 효과를 해결한 후, 피트 위즈덤이 입은 피해 1점을 치료합니다."},{"id":"41019","name":"집중된 힘","en":"Directed Force","type":"event","enc":false,"unique":false,"cost":0,"res":"R","cls":"Basic","tr":["SKILL"],"traits":["기술"],"text":"<b>히어로 난입</b>: 당신의 히어로가 키워드<i>(압살, 관통, 원거리)</i>를 가진 공격을 할 때, 그 공격은 피해 2점을 추가로 입힙니다. (공격마다 최대 1장.)"},{"id":"41020","name":"비상하는 마음","en":"Soaring Hearts","type":"event","enc":false,"unique":false,"cost":2,"res":"G","cls":"Basic","tr":["AERIAL","PSIONIC"],"teamUp":["Angel","Psylocke"],"maxDeck":1,"traits":["공중","사이오닉"],"text":"협력(엔젤 그리고 사일록). 덱마다 최대 1장.\n<b>히어로 행동</b>: 당신의 버린 더미에서 아이덴티티 전용 이벤트 1장을 찾아 당신의 손에 더합니다. 엔젤과 사일록을 준비합니다."},{"id":"41021","name":"정신의 힘","en":"The Power of the Mind","type":"resource","enc":false,"unique":false,"res":"B","cls":"Basic","tr":[],"traits":[],"text":"[[사이오닉]] 카드의 비용을 지불하는 동안, 이 카드가 생성하는 자원의 수가 두 배가 됩니다.","link":"40028"},{"id":"41022","name":"IPAC","en":"* IPAC","type":"support","enc":false,"unique":true,"cost":1,"res":"B","cls":"Basic","tr":["VEHICLE","X-FORCE"],"traits":["탈것","엑스포스"],"text":"당신의 아이덴티티에게 [[엑스포스]] 특성이 있을 때만 플레이합니다.\n<b>히어로 행동</b>: IPAC을 소진하고 플레이어 하나에게 뒷면 조우 카드 1장을 나누어 줌 → 그 플레이어가 카드 2장을 뽑음."},{"id":"41023","name":"X-벙커","en":"* X-Bunker","type":"support","enc":false,"unique":true,"cost":2,"res":"Y","cls":"Basic","tr":["LOCATION","X-FORCE"],"traits":["장소","엑스포스"],"text":"<b>행동</b>: X-벙커를 소진하고 아이덴티티에게 [[뮤턴트]] 특성이 있는 플레이어 하나를 선택 → 그 플레이어는 자신의 덱 맨 위 카드 X장 중에서 아무 카드 1장을 찾아 자신의 손에 더함. X는 승점 구역에 있는 부가 음모의 수. <i>(덱을 섞습니다.)</i>"},{"id":"41024","name":"텔레파시","en":"Telepathy","type":"upgrade","enc":false,"unique":false,"cost":1,"res":"B","cls":"Basic","tr":["PSIONIC","SUPERPOWER"],"maxPer":1,"traits":["사이오닉","슈퍼파워"],"text":"당신의 아이덴티티에게 [[사이오닉]] 특성이 있을 때만 플레이합니다. 플레이어마다 최대 1장.\n<b>히어로 행동</b><i>(저지)</i>: 텔레파시를 소진하고 [mental][mental] 자원을 소모 → 음모 하나에서 위협을 2만큼 제거."},{"id":"41025","name":"몸이 바뀌다","en":"Body Swapped","type":"obligation","enc":true,"set":"Psylocke","unique":false,"boost":2,"tr":[],"traits":[],"text":"<b><i>벳시 브래독 플레이어에게 이 카드를 줍니다.</i></b>\n당신은 당신의 사이 카타나 업그레이드를 뒤집을 수 없습니다.\n<b>공개될 때</b>: 당신의 각 [[사이 에너지]] 업그레이드를 사이 카타나 면으로 뒤집고 소진합니다.\n<b>일상 행동</b>: 당신의 손에서 [[사이오닉]] 카드 1장을 버림 → 이 의무 카드를 버림."},{"id":"41026","name":"키메라","en":"* Chimera","type":"minion","enc":true,"set":"Psylocke Nemesis","unique":true,"hp":5,"atk":1,"sch":1,"boost":3,"tr":["MARAUDER","PSIONIC"],"nemesis":true,"traits":["머로더","사이오닉"],"text":"[star] <b>강제 난입</b>: 키메라가 당신을 상대로 활성화할 때, 이번 활성화에서 그녀는 음모 +X와 공격 +X를 받습니다. X는 당신이 조종하는 카드에 있는 [mental] 자원의 수입니다.","star":true},{"id":"41027","name":"차원 간 약탈","en":"Interdimensional Plunder","type":"side","enc":true,"set":"Psylocke Nemesis","unique":false,"boost":3,"start":2,"accel":1,"tr":[],"traits":[],"text":"<b>공개될 때</b>: 플레이 영역에 있는 업그레이드마다 이 카드에 위협을 1만큼 놓습니다."},{"id":"41028","name":"사이오닉 환영","en":"Psionic Illusion","type":"attachment","enc":true,"set":"Psylocke Nemesis","unique":false,"boost":2,"tr":["PSIONIC"],"traits":["사이오닉"],"text":"당신의 아이덴티티에 장착합니다.\n<b>강제 난입</b>: 당신이 적을 공격할 때, 자원 유형 하나를 선언하고 당신의 덱 맨 위에서 카드 1장을 버립니다. 그 카드에 선언한 유형의 자원이 없다면, 이 공격의 대상을 당신이 선택한 아군 캐릭터로 바꾸고 이 카드를 버립니다."},{"id":"41029","name":"염동력의 용","en":"Telekinetic Dragon","type":"treachery","enc":true,"set":"Psylocke Nemesis","unique":false,"tr":[],"traits":[],"text":"<b>공개될 때</b>: 간접 피해 X점을 입습니다. X는 당신이 조종하는 카드에 있는 [mental] 자원의 수입니다. X가 0이라면, 이 카드는 쇄도를 얻습니다.\n<hr />\n[star] <b>강화</b>: [mental] 자원을 소모하거나 당신의 아이덴티티를 혼란에 빠뜨리는 것 중 하나를 선택합니다.","star":true,"boostStar":true},{"id":"41030","name":"사이 보우 공격","en":"Psi-Bow Attack","type":"event","enc":false,"unique":false,"cost":2,"res":"Y","cls":"Aggression","tr":["ATTACK","PSIONIC"],"traits":["공격","사이오닉"],"text":"당신의 히어로에게 [[사이오닉]] 특성이 있을 때만 플레이합니다.\n<b>히어로 행동</b><i>(공격)</i>: 적 하나에게 피해 4점을 입힙니다. 이 공격은 원거리를 얻습니다."},{"id":"41031","name":"도미노","en":"* Domino","type":"ally","enc":false,"sub":"니나 서먼","unique":true,"hp":3,"atk":2,"atkStar":true,"thw":1,"thwStar":true,"cost":3,"res":"G","cls":"Leadership","tr":["POSSE","X-FORCE"],"traits":["패거리","엑스포스"],"text":"[star] <b>반응</b>: 당신이 도미노의 기본 기능 중 하나를 사용한 후, 당신의 손에 있는 카드 1장과 당신의 덱 맨 위 카드를 맞바꿉니다.","star":true},{"id":"41032","name":"사이 플레일 타격","en":"Psi-Flail Strike","type":"event","enc":false,"unique":false,"cost":2,"res":"Y","cls":"Protection","tr":["ATTACK","PSIONIC"],"traits":["공격","사이오닉"],"text":"당신의 히어로에게 [[사이오닉]] 특성이 있을 때만 플레이합니다.\n<b>히어로 반응</b><i>(공격)</i>: 당신이 적의 공격을 방어한 후, 그 적에게 피해 3점을 입히고 그 적을 기절시킵니다."},{"id":"41033","name":"염동력","en":"Telekinesis","type":"upgrade","enc":false,"unique":false,"cost":1,"res":"B","cls":"Basic","tr":["PSIONIC","SUPERPOWER"],"maxPer":1,"traits":["사이오닉","슈퍼파워"],"text":"당신의 히어로에게 [[사이오닉]] 특성이 있을 때만 플레이합니다. 플레이어마다 최대 1장.\n<b>히어로 행동</b><i>(공격)</i>: 염동력을 소진하고 [mental][mental] 자원을 소모 → 적 하나에게 피해 3점을 입힘."}]});
